    "3": "3루수",
    "3B": "3루수",
    "삼": "3루수",
    "三": "3루수",

    /* 유격 */
    "유": "유격수",
    "遊": "유격수",
    "SS": "유격수",

    /* 외야 */
    "좌": "좌익수",
    "左": "좌익수",
