  /* FROZEN_GAME_PREDICTIONS_LOAD_V1 */
  useEffect(() => {
    const startedGames =
      games.filter(
        (game) =>
          game.status.stateCode === "2" ||
          game.status.stateCode === "3"
      );

    if (startedGames.length === 0) {
      return;
    }

    let cancelled = false;

    async function loadFrozenGamePredictions() {
      try {
        const response = await fetch(
          "/api/predictions/live?engineVersion=v0.1&scope=ALL",
          { cache: "no-store" }
        );

        if (!response.ok) {
          return;
        }

        const json = await response.json();
        const rows = Array.isArray(json?.predictions)
          ? json.predictions
          : [];

        const startedIds = new Set(
          startedGames.map((game) => game.gameId)
        );

        const latest = new Map<string, any>();

        for (const item of rows) {
          if (
            item?.date !== date ||
            !startedIds.has(String(item?.gameId || "")) ||
            !["ML", "HANDICAP", "TOTAL"].includes(String(item?.market || ""))
          ) {
            continue;
          }

          const key = `${item.gameId}:${item.market}`;
          const previous = latest.get(key);

          if (
            !previous ||
            String(item.capturedAt || "") >
              String(previous.capturedAt || "")
          ) {
            latest.set(key, item);
          }
        }

        const next: Record<string, Pick[]> = {};

        for (const item of latest.values()) {
          const grade: Pick["grade"] =
            item.grade === "A" ||
            item.grade === "B"
              ? item.grade
              : "C";

          const market = item.market as Pick["market"];
          const oddsValue = Number(item.odds);
          const confidenceValue = Number(item.confidence);
          const evValue =
            item.ev === null ||
            item.ev === undefined
              ? null
              : Number(item.ev);

          if (
            !Number.isFinite(oddsValue) ||
            !Number.isFinite(confidenceValue)
          ) {
            continue;
          }

          const pick: Pick = {
            gameId: String(item.gameId),
            label: String(item.label || ""),
            market,
            odds: oddsValue,
            grade,
            confidence: confidenceValue,
            ev:
              evValue === null ||
              Number.isFinite(evValue)
                ? evValue
                : null,
          };

          if (!next[pick.gameId]) {
            next[pick.gameId] = [];
          }

          next[pick.gameId].push(pick);
        }

        if (!cancelled) {
          setFrozenGamePredictions((prev) => ({
            ...prev,
            ...next,
          }));
        }
      } catch {
      }
    }

    void loadFrozenGamePredictions();

    return () => {
      cancelled = true;
    };
  }, [date, games]);


