  const featuredCombos =
    useMemo(
      () => {
        const selected:
          typeof practicalComboCandidates = [];

        const usedPickCounts =
          new Map<string, number>();

        const pickKey = (
          pick: Pick
        ) =>
          `${pick.gameId}:${pick.market}:${pick.label}`;

        for (
          const leg of
          [1, 2, 3, 4, 5]
        ) {
          const candidates =
            practicalComboCandidates.filter(
              (combo) =>
                combo.picks.length === leg
            );

          /*
            상단 1~5폴 추천 전체에서 같은 픽은
            최대 2번까지만 허용한다.

            조건을 만족하는 후보가 전혀 없을 때만
            원래 후보군으로 되돌아간다.
          */
          const diversifiedCandidates =
            candidates.filter(
              (combo) =>
                combo.picks.every(
                  (pick) =>
                    (
                      usedPickCounts.get(
                        pickKey(pick)
                      ) || 0
                    ) < 2
                )
            );

          const recommendationPool =
            diversifiedCandidates.length
              ? diversifiedCandidates
              : candidates;

          const ranked =
            recommendationPool
              .map((combo) => {
                const gradeAverage =
                  combo.picks.reduce(
                    (sum, pick) =>
                      sum +
                      (
                        pick.grade === "A"
                          ? 3
                          : pick.grade === "B"
                            ? 2
                            : 1
                      ),
                    0
                  ) /
                  Math.max(
                    1,
                    combo.picks.length
                  );

                const negativeEvCount =
                  combo.picks.filter(
                    (pick) =>
                      (pick.ev ?? -1) < 0
                  ).length;

                const gameCounts =
                  new Map<string, number>();

                for (
                  const pick of
                  combo.picks
                ) {
                  gameCounts.set(
                    pick.gameId,
                    (
                      gameCounts.get(
                        pick.gameId
                      ) || 0
                    ) + 1
                  );
                }

                const sameGameExtra =
                  [...gameCounts.values()]
                    .filter(
                      (count) =>
                        count > 1
                    ).length;

                const repeatedPickPenalty =
                  combo.picks.reduce(
                    (sum, pick) =>
                      sum +
                      (
                        usedPickCounts.get(
                          pickKey(pick)
                        ) || 0
                      ),
                    0
                  );

                /*
                  폴 수별 후보 안에서만 비교한다.

                  예상 적중률을 기본으로 하되
                  EV·등급·배당 효율을 반영하고,
                  음수 EV·같은 경기 집중·반복 픽을 감점한다.
                */
                const score =
                  combo.probability * 100 * 0.48 +
                  combo.averageConfidence * 100 * 0.18 +
                  (combo.averageEv ?? -1) * 100 * 0.22 +
                  gradeAverage * 2.2 +
                  Math.log(
                    Math.max(
                      1,
                      combo.odds
                    )
                  ) * 2.5 -
                  negativeEvCount * 2.5 -
                  sameGameExtra * 2 -
                  repeatedPickPenalty * 3.5;

                return {
                  combo,
                  score,
                };
              })
              .sort(
                (a, b) =>
                  b.score - a.score
              );

          const best =
            ranked[0]?.combo;

          if (!best) {
            continue;
          }

          selected.push(best);

          for (
            const pick of
            best.picks
          ) {
            const key =
              pickKey(pick);

            usedPickCounts.set(
              key,
              (
                usedPickCounts.get(key) ||
                0
              ) + 1
            );
          }
        }

        return selected;
      },
      [practicalComboCandidates]
    );

